using System.Reflection;
using Microsoft.Extensions.DependencyInjection;

var asm = typeof(ModelContextProtocol.Server.McpServerTool).Assembly;
// Find extension methods on IMcpServerBuilder
var builderExtType = asm.GetTypes()
    .Where(t => t.Name == "McpServerBuilderExtensions")
    .FirstOrDefault();
if (builderExtType != null) {
    foreach (var m in builderExtType.GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(m => m.Name.Contains("Stdio") || m.Name.Contains("Transport") || m.Name.Contains("WithTool") || m.Name.Contains("WithPrompt"))
        .OrderBy(m => m.Name))
        Console.WriteLine($"  {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
}

// Check for other extension classes with Transport
Console.WriteLine("\nClasses with transport methods:");
foreach (var t in asm.GetTypes().Where(t => t.IsPublic && t.GetMethods(BindingFlags.Public | BindingFlags.Static).Any(m => m.Name.Contains("Stdio") || m.Name.Contains("Transport"))))
    Console.WriteLine("  " + t.FullName);

// Also check ServiceCollection extensions
Console.WriteLine("\nMcpServerServiceCollectionExtensions:");
var svcExt = asm.GetTypes().FirstOrDefault(t => t.Name == "McpServerServiceCollectionExtensions");
if (svcExt != null) {
    foreach (var m in svcExt.GetMethods(BindingFlags.Public | BindingFlags.Static))
        Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
}
EOF
